crosoft\Windows\Personalization';N='NoLockScreen'},@{H='HKLM';P='SOFTWARE\Policies\Microsoft\Windows\System';N='UserPolicyMode'});foreach($r in $regs){$p="$($r.H):\$($r.P)";if(Test-Path $p){Remove-ItemProperty -Path $p -Name $r.N -Force -ErrorAction SilentlyContinue;Write-Host "Deleted: $p -> $($r.N)" -ForegroundColor Green}else{Write-Host "Key missing: $p" -ForegroundColor DarkYellow}}
